void opeu_end_orders(uint8_t ds[65536]) {
  UNIT_P  a;
  uint8_t b, c;
  if (BATTLE_DIRECTION == 255)
    return;
  a = FIND_UNIT(BATTLE_X, BATTLE_Y);
  if (a && (UNIT_GROUP_FLAGS(a) & 8) && UNIT_ORDER(a) != 255)
    RESTORE(a);
  b = BATTLE_X;
  c = BATTLE_Y;
  GRID_STEP(&b, &c, BATTLE_DIRECTION);
  a = FIND_UNIT(b, c);
  if (a && (UNIT_GROUP_FLAGS(a) & 8) && UNIT_ORDER(a) != 255)
    RESTORE(a);
}

