void opeu_notice_end(uint8_t ds[65536], HostEvent event, uint16_t sp) {
  TURN_PREPARE();
  LOSSES();
  SELECT(0);
  SELECT(1);
  OCCUPY();
  LEADERS();
  MORALE();
  ORDERS();
  opeu_end_nothing();
  if (CONTROL(1) == 0 && CONTROL(0) == 1) {
    SET_DAILY_ACTIVE(1);
    DAILY(0);
    SET_DAILY_ACTIVE(0);
  }
  if (CONTROL(0) == 0 && CONTROL(1) == 1) {
    SET_DAILY_ACTIVE(1);
    DAILY(1);
    SET_DAILY_ACTIVE(0);
  }
  if (CONTROL(0) == 0 && CONTROL(1) == 0) {
    CACHED_SIDE = 255;
    SET_DAILY_ACTIVE(1);
    DAILY((uint8_t)(STATUS(1) == 1));
    SET_DAILY_ACTIVE(0);
  }
}

